const input = $input.first().json;
const body = input.body || {};
const msg = body.message || {};
const conv = body.conversation || {};

let messageText = '';
let attachments = [];

if (msg.type === 'text' && msg.text) {
  messageText = msg.text.body || '';
} else if (msg.type === 'image' && msg.image) {
  messageText = msg.image.caption || '[Imagen recibida]';
  attachments.push({ type: 'image', url: msg.image.link || '', mime_type: msg.image.mime_type || 'image/jpeg' });
} else if (msg.type === 'document' && msg.document) {
  messageText = msg.document.caption || '[Documento recibido]';
  attachments.push({ type: 'document', url: msg.document.link || '', mime_type: msg.document.mime_type || 'application/pdf' });
} else if (msg.type === 'voice' && msg.voice) {
  messageText = '[Mensaje de voz recibido]';
  attachments.push({ type: 'voice', url: msg.voice.link || '', mime_type: msg.voice.mime_type || 'audio/ogg' });
} else if (msg.type === 'audio' && msg.audio) {
  messageText = '[Audio recibido]';
  attachments.push({ type: 'audio', url: msg.audio.link || '', mime_type: msg.audio.mime_type || 'audio/mpeg' });
}

const phoneNumber = conv.phone_number ? '+' + conv.phone_number : (msg.from ? '+' + msg.from : '');

return [{
  json: {
    core_workflow_id: 'CUSTOMER_SERVICE_CORE_ID',
    channel: 'kapso-wa',
    conversation_id: String(conv.id || msg.from || ''),
    user_id: String(phoneNumber || ''),
    message: messageText,
    attachments: attachments,
    metadata: {
      message_id: msg.id || '',
      contact_name: conv.contact_name || '',
      phone: phoneNumber,
      phone_number_id: conv.phone_number_id || ''
    }
  }
}];
